CREATE TABLE IF NOT EXISTS platform_settings(id TEXT PRIMARY KEY CHECK(id='default'),view_bps INTEGER NOT NULL CHECK(view_bps BETWEEN 0 AND 5000),use_bps INTEGER NOT NULL CHECK(use_bps BETWEEN 0 AND 5000),hold_days INTEGER NOT NULL CHECK(hold_days BETWEEN 1 AND 30),updated_by TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS idea_reviews(idea_id TEXT PRIMARY KEY REFERENCES ideas(id),status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected','suspended')),reason TEXT,reviewer_id TEXT,reviewed_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS idea_quality(idea_id TEXT PRIMARY KEY REFERENCES ideas(id),originality TEXT NOT NULL,validation_note TEXT NOT NULL,risks TEXT NOT NULL,content_hash TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS listing_terms(idea_id TEXT PRIMARY KEY REFERENCES ideas(id),view_bps INTEGER NOT NULL,use_bps INTEGER NOT NULL,hold_days INTEGER NOT NULL,version TEXT NOT NULL,text TEXT NOT NULL,agreed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS order_financials(order_id TEXT PRIMARY KEY REFERENCES orders(id),seller_id TEXT NOT NULL REFERENCES users(id),gross INTEGER NOT NULL,commission_bps INTEGER NOT NULL CHECK(commission_bps BETWEEN 0 AND 5000),platform_fee INTEGER NOT NULL,seller_amount INTEGER NOT NULL,hold_until TEXT NOT NULL,CHECK(platform_fee+seller_amount=gross));
CREATE TABLE IF NOT EXISTS payout_requests(id TEXT PRIMARY KEY,seller_id TEXT NOT NULL REFERENCES users(id),amount INTEGER NOT NULL CHECK(amount>0),status TEXT NOT NULL CHECK(status IN ('requested','paid','cancelled')),created_at TEXT NOT NULL,paid_at TEXT,handled_by TEXT);
CREATE TABLE IF NOT EXISTS settlement_items(order_id TEXT PRIMARY KEY REFERENCES order_financials(order_id),payout_id TEXT REFERENCES payout_requests(id),voided_at TEXT);
CREATE TABLE IF NOT EXISTS cases(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),idea_id TEXT NOT NULL REFERENCES ideas(id),order_id TEXT REFERENCES orders(id),kind TEXT NOT NULL CHECK(kind IN ('report','refund','dispute')),reason TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('open','reviewing','resolved','rejected')),resolution TEXT,seller_response TEXT,created_at TEXT NOT NULL,closed_at TEXT,handled_by TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS cases_one_open ON cases(user_id,idea_id,kind) WHERE status IN ('open','reviewing');
CREATE TABLE IF NOT EXISTS refunds(id TEXT PRIMARY KEY,order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),gross_reversal INTEGER NOT NULL,fee_reversal INTEGER NOT NULL,seller_reversal INTEGER NOT NULL,reason TEXT NOT NULL,handled_by TEXT NOT NULL,created_at TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode='test'));
CREATE TABLE IF NOT EXISTS audit_events(id TEXT PRIMARY KEY,actor_id TEXT NOT NULL,action TEXT NOT NULL,target_id TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS cases_idea_status ON cases(idea_id,status);
CREATE INDEX IF NOT EXISTS finance_seller ON order_financials(seller_id,hold_until);
CREATE TABLE IF NOT EXISTS access_records(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,idea_id TEXT NOT NULL REFERENCES ideas(id),kind TEXT NOT NULL CHECK(kind IN ('detail','image')),actor_role TEXT NOT NULL,version INTEGER NOT NULL,content_hash TEXT,first_accessed_at TEXT NOT NULL,UNIQUE(user_id,idea_id,kind));
CREATE TABLE IF NOT EXISTS idea_taxonomy(idea_id TEXT PRIMARY KEY REFERENCES ideas(id),topic TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS taxonomy_topic ON idea_taxonomy(topic);
CREATE TABLE IF NOT EXISTS idea_classification(idea_id TEXT PRIMARY KEY REFERENCES ideas(id),kind TEXT NOT NULL,topic TEXT NOT NULL,domains TEXT NOT NULL,version TEXT NOT NULL,confirmed_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS classification_kind_topic ON idea_classification(kind,topic);
CREATE TABLE IF NOT EXISTS listing_requests(id TEXT PRIMARY KEY,seller_id TEXT NOT NULL REFERENCES users(id),idea_id TEXT NOT NULL REFERENCES ideas(id),kind TEXT NOT NULL CHECK(kind IN ('create','revise')),payload_hash TEXT NOT NULL,version INTEGER NOT NULL,token TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS listing_requests_seller ON listing_requests(seller_id,created_at);
CREATE TABLE IF NOT EXISTS upload_cleanup(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),object_key TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS upload_cleanup_owner ON upload_cleanup(owner_id,created_at);
CREATE INDEX IF NOT EXISTS orders_idea ON orders(idea_id);
CREATE TABLE IF NOT EXISTS order_price_guidance(order_id TEXT PRIMARY KEY REFERENCES orders(id),guidance TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS shared_ideas(id TEXT PRIMARY KEY,author_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,summary TEXT NOT NULL,body TEXT NOT NULL,category TEXT NOT NULL,topic TEXT NOT NULL,license TEXT NOT NULL CHECK(license IN ('discussion','attribution')),license_text TEXT NOT NULL,terms_version TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','published','rejected','hidden')),version INTEGER NOT NULL DEFAULT 1,request_id TEXT NOT NULL UNIQUE,payload_hash TEXT NOT NULL,review_reason TEXT,reviewer_id TEXT,reviewed_at TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS shared_ideas_status_category ON shared_ideas(status,category,created_at);
CREATE INDEX IF NOT EXISTS shared_ideas_author ON shared_ideas(author_id,created_at);
CREATE TABLE IF NOT EXISTS share_value_sources(share_id TEXT PRIMARY KEY REFERENCES shared_ideas(id),content_hash TEXT NOT NULL,source_version INTEGER NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS share_value_opinions(id TEXT PRIMARY KEY,share_id TEXT NOT NULL REFERENCES shared_ideas(id),user_id TEXT NOT NULL REFERENCES users(id),source_hash TEXT NOT NULL,source_version INTEGER NOT NULL,source_title TEXT NOT NULL,source_category TEXT NOT NULL,source_topic TEXT NOT NULL,source_license TEXT NOT NULL,source_license_text TEXT NOT NULL,source_terms_version TEXT NOT NULL,question_version TEXT NOT NULL,maturity TEXT NOT NULL CHECK(maturity IN ('seed','developed','professional')),view_amount INTEGER CHECK(view_amount IS NULL OR (view_amount BETWEEN 0 AND 100000000)),use_amount INTEGER CHECK(use_amount IS NULL OR (use_amount BETWEEN 0 AND 100000000)),reason TEXT NOT NULL,role_snapshot TEXT NOT NULL CHECK(role_snapshot IN ('seller','buyer')),state TEXT NOT NULL CHECK(state IN ('active','withdrawn')),moderation TEXT NOT NULL CHECK(moderation IN ('normal','excluded')),moderation_reason TEXT,moderation_by TEXT,moderation_at TEXT,revision INTEGER NOT NULL CHECK(revision>=1),payload_hash TEXT NOT NULL,write_token TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,CHECK(view_amount IS NOT NULL OR use_amount IS NOT NULL),UNIQUE(share_id,user_id,source_hash,question_version));
CREATE INDEX IF NOT EXISTS share_value_public ON share_value_opinions(share_id,source_hash,question_version,state,moderation);
CREATE INDEX IF NOT EXISTS share_value_user ON share_value_opinions(user_id,updated_at);
CREATE INDEX IF NOT EXISTS share_value_period ON share_value_opinions(question_version,updated_at);
CREATE TABLE IF NOT EXISTS idea_patents(idea_id TEXT PRIMARY KEY REFERENCES ideas(id),listing_version INTEGER NOT NULL, declaration TEXT NOT NULL,review_state TEXT NOT NULL CHECK(review_state IN ('pending','recorded','needs_info','expert_required')),revision INTEGER NOT NULL DEFAULT 0 CHECK(revision>=0),review TEXT,review_token TEXT,reviewer_id TEXT,reviewed_at TEXT,declared_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idea_patents_review ON idea_patents(review_state,declared_at);
CREATE TABLE IF NOT EXISTS order_patent_disclosures(order_id TEXT PRIMARY KEY REFERENCES orders(id),snapshot TEXT NOT NULL,policy_version TEXT NOT NULL,created_at TEXT NOT NULL);
